SELECT COUNT(DISTINCT srescode) FROM sprint_results WHERE matchref IN (
    SELECT sr.matchref FROM sprint_results sr
    GROUP BY sr.matchref
    HAVING MIN(CASE WHEN sr.sprint_performance->'timing'->>'final_time' LIKE '+%' THEN CAST(SUBSTRING(sr.sprint_performance->'timing'->>'final_time' FROM '\d+\.\d+') AS numeric) END) > 5
);

SELECT COUNT(DISTINCT rno) FROM sprint_results WHERE matchref IN (
    SELECT sr.matchref FROM sprint_results sr
    GROUP BY sr.matchref
    HAVING MIN(CASE WHEN sr.sprint_performance->'timing'->>'final_time' LIKE '+%' THEN CAST(SUBSTRING(sr.sprint_performance->'timing'->>'final_time' FROM '\d+\.\d+') AS numeric) END) > 5
);

